if($section==='media'){
    $search=mb_substr(trim((string)($_GET['q']??'')),0,120);$kind=$_GET['kind']??'';
    $sql='SELECT m.* FROM media m LEFT JOIN media_state s ON s.media_id=m.id WHERE s.deleted_at IS NULL';$params=[];
    if($user['role']==='contributor'){$sql.=' AND m.uploaded_by=?';$params[]=$user['id'];}
    if($search){$sql.=' AND (m.original_name LIKE ? OR m.alt_text LIKE ?)';$params[]='%'.$search.'%';$params[]='%'.$search.'%';}
    if(in_array($kind,['image','video'],true)){$sql.=' AND m.mime_type LIKE ?';$params[]=$kind.'/%';}elseif($kind==='document')$sql.=" AND m.mime_type NOT LIKE 'image/%' AND m.mime_type NOT LIKE 'video/%'";
    $q=db()->prepare($sql.' ORDER BY m.created_at DESC LIMIT 100');$q->execute($params);$library=$q->fetchAll();admin_header('Media & Documents','media'); ?>
