    $files=db()->query('SELECT m.id,m.original_name,s.deleted_at FROM media m JOIN media_state s ON s.media_id=m.id WHERE s.deleted_at IS NOT NULL ORDER BY s.deleted_at DESC')->fetchAll(); ?>
